package com.muxigame.city;
import com.google.gson.*;import java.util.*;import java.nio.file.*;
import net.minecraft.core.*;import net.minecraft.core.component.DataComponents;import net.minecraft.nbt.*;import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.Entity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.component.CustomData;import net.minecraft.world.level.saveddata.SavedData;import net.minecraft.world.level.storage.LevelResource;import net.neoforged.neoforge.network.PacketDistributor;
/** Independent city public-order ledger. No invented money, residents or social-stability adjustments. */
public final class CityLaw extends SavedData {
 static final class Record{JsonObject rules=defaults();long revision;final List<String> journal=new ArrayList<>();}
 final Map<UUID,Record> records=new LinkedHashMap<>();
 public static CityLaw get(MinecraftServer s){return s.overworld().getDataStorage().computeIfAbsent(new Factory<>(CityLaw::new,CityLaw::load),"city_law");}
 static JsonObject defaults(){var n=new JsonObject();n.addProperty("enabled",true);n.addProperty("security",100);n.addProperty("guardLoss",2);n.addProperty("useLoss",1);n.addProperty("saleLoss",4);n.addProperty("cooldownTicks",100);return n;}
 static JsonObject validate(JsonObject n){CityEconomy.require(n!=null&&n.keySet().equals(defaults().keySet()),"治安配置字段不完整");CityEconomy.require(n.get("enabled").isJsonPrimitive()&&n.get("enabled").getAsJsonPrimitive().isBoolean(),"enabled必须是布尔值");for(String k:List.of("security","guardLoss","useLoss","saleLoss","cooldownTicks")){int v=n.get(k).getAsBigDecimal().intValueExact();CityEconomy.require(v>=0&&v<=(k.equals("cooldownTicks")?12000:100),"治安值/扣减值0–100，冷却0–12000tick");}return n.deepCopy();}
 Record record(UUID id){return records.computeIfAbsent(id,k->new Record());}
 public static int security(MinecraftServer s,UUID id){var v=get(s).records.get(id);return v==null?100:v.rules.get("security").getAsInt();}
 static int patrol(MinecraftServer server,UUID city,int target,boolean staffed,int recovery,int decay,long tick){
  var data=get(server);var r=data.record(city);int old=r.rules.get("security").getAsInt();if(!r.rules.get("enabled").getAsBoolean())return old;
  int next=target>old&&staffed?Math.min(target,old+recovery):target<old?Math.max(target,old-decay):old;
  if(next!=old){r.rules.addProperty("security",next);r.revision++;r.journal.add("tick "+tick+" · 驻军值勤结算 · 治安 "+old+"→"+next);while(r.journal.size()>32)r.journal.removeFirst();data.setDirty();}return next;
 }
 public static CompoundTag origin(Entity npc){var out=new CompoundTag();if(npc.getServer()==null)return out;var d=CityData.get(npc.getServer());var c=CityNpcBridge.home(d,npc.getUUID());if(c==null)c=d.cities().stream().filter(v->v.dimension.equals(npc.level().dimension().location().toString())&&v.includes(npc.blockPosition())).findFirst().orElse(null);out.putString("Dimension",npc.level().dimension().location().toString());out.putLong("Position",npc.blockPosition().asLong());out.putString("CityName",c==null?"无属地 · "+npc.blockPosition().toShortString():c.name);if(c!=null)out.putUUID("CityId",c.id);return out;}
 public static CompoundTag stolen(ItemStack stack){return stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound("cpn_stolen");}
 public static boolean tradeGood(ItemStack stack,net.minecraft.world.item.Item item){if(stack.isEmpty()||stack.getItem()!=item||stolen(stack).isEmpty())return false;var copy=stack.copy();var data=copy.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();data.remove("cpn_stolen");if(data.isEmpty())copy.remove(DataComponents.CUSTOM_DATA);else copy.set(DataComponents.CUSTOM_DATA,CustomData.of(data));return ItemStack.isSameItemSameComponents(copy,new ItemStack(item));}
 /** Compatibility hook for CustomNPCs. Interrogation is not implemented: never charge security here.
  * Ownership components and the caller's NPC reaction remain unchanged. Old rules are kept for saves/API.
  */
 public static void penalize(ServerPlayer player,CompoundTag stolen,String action,Entity guard){}
 static void backup(ServerPlayer p,UUID id,Record r)throws Exception{Path dir=p.server.getWorldPath(LevelResource.ROOT).resolve("city_settlements/law/"+id);Files.createDirectories(dir);Files.writeString(dir.resolve(System.currentTimeMillis()+"-"+UUID.randomUUID().toString().substring(0,8)+".json"),CityEconomy.JSON.toJson(r.rules),StandardOpenOption.CREATE_NEW);}
 public static void request(ServerPlayer p,CityNetwork.Request req){String msg="已读取城市治安";try{UUID id=UUID.fromString(req.city());var c=CityData.get(p.server).require(id);CityEconomy.require(p.hasPermissions(2)||c.owner.equals(p.getUUID()),"治安编辑需要城市所有者或管理员");var data=get(p.server);var r=data.record(id);
  if(!req.op().equals("lawread")&&!req.op().equals("lawexport")){CityEconomy.require(r.revision==req.revision(),"治安记录已变化，请刷新后重试");JsonObject next;
   if(req.op().equals("lawdefault"))next=defaults();else if(req.op().equals("lawrollback")){Path dir=p.server.getWorldPath(LevelResource.ROOT).resolve("city_settlements/law/"+id);CityEconomy.require(Files.exists(dir),"没有可回退备份");try(var files=Files.list(dir)){var list=files.filter(f->f.getFileName().toString().matches("[0-9]{13}-[a-f0-9]{8}\\.json")).sorted(Comparator.reverseOrder()).toList();CityEconomy.require(!list.isEmpty(),"没有可回退备份");next=JsonParser.parseString(Files.readString(list.getFirst())).getAsJsonObject();}}else{CityEconomy.require(Set.of("lawsave","lawimport").contains(req.op()),"未知治安操作");next=JsonParser.parseString(req.value()).getAsJsonObject();}
   next=validate(next);backup(p,id,r);r.rules=next;r.revision++;data.setDirty();msg="已保存治安配置；修改前版本已备份";
  }
  CompoundTag out=new CompoundTag();out.putBoolean("CityLawEditor",true);out.putString("CityId",id.toString());out.putString("Name",c.name);out.putLong("Revision",r.revision);out.putString("Rules",CityEconomy.JSON.toJson(r.rules));out.putString("Message",msg);out.putBoolean("CopyExport",req.op().equals("lawexport"));var lines=new ListTag();for(String line:r.journal)lines.add(StringTag.valueOf(line));out.put("Journal",lines);PacketDistributor.sendToPlayer(p,new CityNetwork.Snapshot(out));
 }catch(Exception ex){var out=new CompoundTag();out.putBoolean("CityLawEditor",true);out.putBoolean("Failed",true);out.putString("Message",ex.getMessage()==null?"治安请求失败":ex.getMessage());PacketDistributor.sendToPlayer(p,new CityNetwork.Snapshot(out));}}
 @Override public CompoundTag save(CompoundTag out,HolderLookup.Provider lookup){out.putInt("Schema",1);var list=new ListTag();records.forEach((id,r)->{var n=new CompoundTag();n.putUUID("City",id);n.putString("Rules",r.rules.toString());n.putLong("Revision",r.revision);var history=new ListTag();r.journal.forEach(s->history.add(StringTag.valueOf(s)));n.put("Journal",history);list.add(n);});out.put("Cities",list);return out;}
 static CityLaw load(CompoundTag n,HolderLookup.Provider lookup){CityEconomy.require(n.getInt("Schema")==1,"不支持的治安数据版本");var data=new CityLaw();var cities=n.getList("Cities",10);CityEconomy.require(cities.size()<=128,"治安城市记录过多");for(var row:cities){var t=(CompoundTag)row;var r=new Record();r.rules=validate(JsonParser.parseString(t.getString("Rules")).getAsJsonObject());r.revision=Math.max(0,t.getLong("Revision"));for(var line:t.getList("Journal",8)){CityEconomy.require(r.journal.size()<32&&line.getAsString().length()<256,"治安历史过大");r.journal.add(line.getAsString());}data.records.put(t.getUUID("City"),r);}return data;}
}
